Procedures.CommandText:
PARAMETERS acode Text ( 255 );
SELECT a_code, sum(amt) AS j_amt, sum(amtf) AS j_amtf
FROM journal
WHERE journal.a_code = [acode]
GROUP BY a_code;

PARAMETERS fcode Text ( 255 ), tcode Text ( 255 );
SELECT a_code, sum(amt) AS j_amt, sum(amtf) AS j_amtf
FROM journal
WHERE journal.a_code >= [fcode] and journal.a_code <= [tcode]
GROUP BY a_code;

PARAMETERS acode Text ( 255 ), tcode Text ( 255 ), acntr Text ( 255 ), tcntr Text ( 255 ), fdate DateTime, tdate DateTime;
SELECT a_code, cost_cntr_no, sum(amt) AS j_amt, sum(amtf) AS j_amtf
FROM journal
WHERE not isnull(cost_cntr_no) and journal.a_code >= [acode] and journal.a_code <=[tcode] and journal.cost_cntr_no >= [acntr] and journal.cost_cntr_no <=[tcntr] and journal.j_date >= [fdate] and journal.j_date < [tdate] and mn_sb=2
GROUP BY a_code;

PARAMETERS acode Text ( 255 ), tcode Text ( 255 ), acntr Text ( 255 ), tcntr Text ( 255 ), fdate DateTime, tdate DateTime;
SELECT a_code, cost_cntr_no, sum(amt) AS j_amt, sum(amtf) AS j_amtf
FROM journal
WHERE not isnull(cost_cntr_no) and journal.a_code >= [acode] and journal.a_code <=[tcode] and journal.cost_cntr_no >= [acntr] and journal.cost_cntr_no <=[tcntr] and journal.j_date >= [fdate] and journal.j_date < [tdate] and mn_sb=2
GROUP BY a_code, cost_cntr_no;

PARAMETERS fdate DateTime, tdate DateTime, mnth1 Long;
SELECT journal.a_code, sum(journal.amt) AS j_amt, sum(journal.amtf) AS j_amtf
FROM journal INNER JOIN account ON journal.a_code = account.a_code
WHERE journal.j_date >= [fdate] And journal.j_date <= [tdate] and journal.mnth <= mnth1 And account.a_report = 'Profit And Loss'
GROUP BY journal.a_code;

PARAMETERS fdate DateTime, tdate DateTime;
SELECT gr_detail.i_code, sum((c_qty+(sc_qty/iif(not isnull(i_size),i_size,1)))*stk_cost) /sum(c_qty+(sc_qty/iif(not isnull(i_size),i_size,1))) AS av_cst
FROM gr_detail, gr_note, item_detail
WHERE gr_detail.gr_no = gr_note.gr_no And gr_detail.pi_type = gr_note.pi_type And gr_note.gr_date >= fdate And gr_note.gr_date <= tdate And item_detail.i_code = gr_detail.i_code
GROUP BY gr_detail.i_code;

PARAMETERS fcode Text ( 255 ), tcode Text ( 255 ), fdate DateTime, tdate DateTime;
SELECT i_code, w_code, sum(i_qty) AS in_qty, sum(si_qty) AS sin_qty
FROM item_mov
WHERE (item_mov.doc_type=2 or item_mov.doc_type=3 or item_mov.doc_type=5 or doc_type=8) and item_mov.i_code >= [fcode] and item_mov.i_code <= [tcode] and item_mov.i_date >= [fdate] and item_mov.i_date < [tdate]
GROUP BY i_code, w_code;

PARAMETERS fcode Text ( 20 ), wcode Long, fdate DateTime, tdate DateTime;
SELECT i_code, sum(i_qty) AS in_qty, sum(si_qty) AS sin_qty
FROM item_mov
WHERE (item_mov.doc_type = 2 Or item_mov.doc_type = 3 Or item_mov.doc_type = 5 Or doc_type = 8) And item_mov.i_code = [fcode] And item_mov.i_date >= [fdate] And item_mov.i_date <= [tdate] and item_mov.w_code = wcode
GROUP BY i_code;

PARAMETERS icode Text ( 255 ), wcode Long, fdate DateTime, tdate DateTime;
SELECT i_code, w_code, sum(i_qty) AS in_qty, sum(si_qty) AS sin_qty
FROM item_mov
WHERE (item_mov.doc_type = 2 Or item_mov.doc_type = 3 Or item_mov.doc_type = 5 Or doc_type = 8) And item_mov.i_code = [icode] And item_mov.i_date >= [fdate] And item_mov.i_date < [tdate] And item_mov.w_code = [wcode]
GROUP BY i_code, w_code;

PARAMETERS icode Text ( 20 );
SELECT sum(i_qty) AS in_qty, sum(si_qty) AS sin_qty
FROM item_mov
WHERE (doc_type = 2 Or doc_type = 3 Or doc_type = 5 Or doc_type = 8) And i_code = [icode];

PARAMETERS icode Text ( 20 ), wcode Long;
SELECT sum(i_qty) AS in_qty, sum(si_qty) AS sin_qty
FROM item_mov
WHERE (doc_type = 2 Or doc_type = 3 Or doc_type = 5 Or doc_type = 8) And i_code = [icode] and w_code=[wcode];

PARAMETERS fcode Text ( 255 ), tcode Text ( 255 ), fdate DateTime, tdate DateTime;
SELECT i_code, w_code, sum(i_qty) AS in_qty
FROM item_mov
WHERE (item_mov.doc_type=2 or item_mov.doc_type=3 or item_mov.doc_type=5 or doc_type=8) and item_mov.i_code >= [fcode] and item_mov.i_code <= [tcode] and item_mov.i_date >= [fdate] and item_mov.i_date < [tdate]
GROUP BY i_code, w_code;

PARAMETERS icode Text ( 255 ), so_no Long;
SELECT i_code, sum(i_qty) AS iqty, sum(sub_qty) AS s_qty
FROM bill_detail
WHERE bill_detail.i_code = [icode] and bill_detail.so_no = [so_no]
GROUP BY i_code;

PARAMETERS icode Text ( 20 ), fdate DateTime, tdate DateTime;
SELECT sum(i_qty) AS si_qty, sum(sub_qty) AS sb_qty
FROM bill_detail, bills
WHERE bills.bill_no=bill_detail.bill_no and bills.bill_type=bill_detail.bill_type and bills.bill_type = 1 and bills.bill_date >= [fdate] and bills.bill_date <=[tdate] and bill_detail.i_code=icode;

PARAMETERS fdate DateTime, tdate DateTime;
SELECT sum(bill_amt*bill_rate) AS mn_sl
FROM bills
WHERE bill_type=1 and bill_date >= [fdate] and bill_date <= [tdate];

